export interface ForgeClient {
  functions: FunctionsApi;
  call(op: string, input: unknown, opts?: CallOptions): Promise<CallResult>;
  changesets: ChangesetsApi;
  imports: ImportsApi;
  admin: AdminApi;
  views: {
  };
  projections: {
  };
  caches: {
  };
  schedules: {
  };
  workflows: {
  };
}

export function createClient(options: ClientOptions): ForgeClient {
  const t = createTransport(options, operations);
  return {
    call: t.call,
    changesets: {
      propose: (input, opts) => t.unwrap(t.call("@bob/coordination/_/changesets.propose", input, opts)),
      get: (id) => t.unwrap(t.call("@bob/coordination/_/changesets.get", { id })),
      preview: (id) => t.unwrap(t.call("@bob/coordination/_/changesets.preview", { id })),
      approve: (id, contentHash) => t.unwrap(t.call("@bob/coordination/_/changesets.approve", { id, contentHash })),
      commit: (id, opts) => t.unwrap(t.call("@bob/coordination/_/changesets.commit", { id }, opts)),
    },
    functions: {
      cancelExecution: (input, opts) => t.unwrap(t.call("@bob/coordination/_/CancelExecution", input, opts)),
      cancelItem: (input, opts) => t.unwrap(t.call("@bob/coordination/_/CancelItem", input, opts)),
      controlPlan: (input, opts) => t.unwrap(t.call("@bob/coordination/_/ControlPlan", input, opts)),
      createPlan: (input, opts) => t.unwrap(t.call("@bob/coordination/_/CreatePlan", input, opts)),
      findExecution: (input, opts) => t.unwrap(t.call("@bob/coordination/_/FindExecution", input, opts)),
      getCapabilities: (input, opts) => t.unwrap(t.call("@bob/coordination/_/GetCapabilities", input, opts)),
      getItem: (input, opts) => t.unwrap(t.call("@bob/coordination/_/GetItem", input, opts)),
      getOperation: (input, opts) => t.unwrap(t.call("@bob/coordination/_/GetOperation", input, opts)),
      getPlan: (input, opts) => t.unwrap(t.call("@bob/coordination/_/GetPlan", input, opts)),
      readEvents: (input, opts) => t.unwrap(t.call("@bob/coordination/_/ReadEvents", input, opts)),
      reconcileItem: (input, opts) => t.unwrap(t.call("@bob/coordination/_/ReconcileItem", input, opts)),
      recordExecutionReceipt: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RecordExecutionReceipt", input, opts)),
      recordProductionEvidence: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RecordProductionEvidence", input, opts)),
      recordValidationReceipt: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RecordValidationReceipt", input, opts)),
      requestDeployment: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RequestDeployment", input, opts)),
      requestExecution: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RequestExecution", input, opts)),
      requestRelease: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RequestRelease", input, opts)),
      requestValidation: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RequestValidation", input, opts)),
      resolveInput: (input, opts) => t.unwrap(t.call("@bob/coordination/_/ResolveInput", input, opts)),
      retryItem: (input, opts) => t.unwrap(t.call("@bob/coordination/_/RetryItem", input, opts)),
      submitExecution: (input, opts) => t.unwrap(t.call("@bob/coordination/_/SubmitExecution", input, opts)),
      triggerPlan: (input, opts) => t.unwrap(t.call("@bob/coordination/_/TriggerPlan", input, opts)),
      updatePlan: (input, opts) => t.unwrap(t.call("@bob/coordination/_/UpdatePlan", input, opts)),
    },
    imports: {
      inspect: (input) => t.unwrap(t.call("@bob/coordination/_/imports.inspect", input)),
      stage: (input) => t.unwrap(t.call("@bob/coordination/_/imports.stage", input)),
    },
    admin: {
      export: () => t.unwrap(t.call("@bob/coordination/_/admin.export", {})),
      import: (snapshot) => t.unwrap(t.call("@bob/coordination/_/admin.import", { snapshot })),
      verify: (snapshot) => t.unwrap(t.call("@bob/coordination/_/admin.verify", { snapshot })),
      fence: (on) => t.unwrap(t.call("@bob/coordination/_/admin.fence", { on })),
      locateSubject: (input) => t.unwrap(t.call("@bob/coordination/_/admin.subjects.locate", input)),
      inspect: (input) => t.unwrap(t.call("@bob/coordination/_/admin.inspect", input)),
    },
    views: {
    },
    projections: {
    },
    caches: {
    },
    schedules: {
    },
    workflows: {
    },
  };
}
